CREATE TABLE workspaces (id text PRIMARY KEY, tenant_id text NOT NULL, name text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_members (workspace_id text NOT NULL REFERENCES workspaces(id), subject_id text NOT NULL, PRIMARY KEY (workspace_id, subject_id));
CREATE TABLE model_catalog (id text PRIMARY KEY, public_model_id text NOT NULL, version text NOT NULL, provider_id text NOT NULL, provider_model_id text NOT NULL, capability text NOT NULL, input_schema_json jsonb NOT NULL, pricing_rule_version text NOT NULL, availability text NOT NULL, features_json jsonb NOT NULL, limits_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes (id text PRIMARY KEY, tenant_id text NOT NULL, subject_id text NOT NULL, workspace_id text NOT NULL REFERENCES workspaces(id), public_model_id text NOT NULL, request_hash text NOT NULL, normalized_request_json jsonb NOT NULL, pricing_rule_version text NOT NULL, status text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs (id text PRIMARY KEY, tenant_id text NOT NULL, subject_id text NOT NULL, workspace_id text NOT NULL REFERENCES workspaces(id), quote_id text, kind text NOT NULL, public_model_id text NOT NULL, request_hash text NOT NULL, frozen_request_json jsonb NOT NULL, status text NOT NULL, version integer NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE provider_executions (id text PRIMARY KEY, job_id text NOT NULL REFERENCES jobs(id), provider_id text NOT NULL, provider_model_id text NOT NULL, provider_request_key text NOT NULL, provider_job_id text, status text NOT NULL, submission_attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets (id text PRIMARY KEY, tenant_id text NOT NULL, workspace_id text NOT NULL REFERENCES workspaces(id), source_job_id text, kind text NOT NULL, status text NOT NULL, storage_bucket text, storage_key text, sha256 text, mime_type text, byte_size bigint, metadata_json jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id text PRIMARY KEY, tenant_id text NOT NULL, subject_id text NOT NULL, workspace_id text NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id text NOT NULL, request_id text NOT NULL, metadata_redacted_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id text PRIMARY KEY, aggregate_type text NOT NULL, aggregate_id text NOT NULL, event_type text NOT NULL, payload_json jsonb NOT NULL, available_at timestamptz NOT NULL, processed_at timestamptz, attempt_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL);
CREATE TABLE idempotency_records (id text PRIMARY KEY, tenant_id text NOT NULL, subject_id text NOT NULL, tool_name text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, response_snapshot_json jsonb NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, created_at timestamptz NOT NULL, UNIQUE (tenant_id, subject_id, tool_name, idempotency_key));
CREATE TABLE webhook_events (id text PRIMARY KEY, provider_id text NOT NULL, provider_event_id text NOT NULL, signature_valid boolean NOT NULL, payload_encrypted bytea, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, processing_result text, UNIQUE (provider_id, provider_event_id));
